#compdef "PROG"
# zsh completion for "PROG", generated by docopt-completion

FN() {
  "TABLES"
  local state=1 expect=0 positional=0 word opt pos i n
  local -a used
  for word in "${(@Q)words[2,CURRENT-1]}"; do
    if (( ! state )); then
      return 1
    elif (( expect )); then
      expect=0
    elif (( ! positional )) && [[ $word = -- ]]; then
      positional=1
      state=$st_sep[state]
    elif (( ! positional )) && [[ $word = --* ]]; then
      if HELPERS_find "${word%%=*}" 1; then
        used+=($opt)
        (( opt_arg[opt] )) && [[ $word != *=* ]] && expect=$opt
      fi
    elif (( ! positional )) && [[ $word = -?* ]]; then
      for (( pos=2; pos<=$#word; pos++ )); do
        if HELPERS_find "-$word[pos]" 0; then
          used+=($opt)
          if (( opt_arg[opt] )); then
            (( pos == $#word )) && expect=$opt
            break
          fi
        fi
      done
    else
      pos=$st_other[state]
      for (( i=1; i<=$#cmd_state; i++ )); do
        if (( cmd_state[i] == state )) && [[ $cmd_name[i] = "$word" ]]; then
          pos=$cmd_next[i]
          break
        fi
      done
      state=$pos
    fi
  done
  (( state )) || return 1

  if (( expect )); then
    HELPERS_source $opt_src[expect]
    return
  elif (( ! positional )) && [[ $PREFIX = --*=* ]]; then
    HELPERS_find "${PREFIX%%=*}" 1 && (( opt_arg[opt] )) || return 1
    compset -P '*='
    HELPERS_source $opt_src[opt]
    return
  fi
  local -a options commands
  if (( ! positional )); then
    for i in ${=st_opts[state]}; do
      (( $used[(Ie)$i] && ! opt_rep[i] )) && continue
      for n in ${=opt_names[i]}; do
        options+=("${n//:/\\:}${opt_desc[i]:+:$opt_desc[i]}")
      done
    done
  fi
  for (( i=1; i<=$#cmd_state; i++ )); do
    (( cmd_state[i] == state )) && commands+=("${cmd_name[i]//:/\\:}${cmd_desc[i]:+:$cmd_desc[i]}")
  done
  if (( ! positional )) && [[ $PREFIX = -* ]] || (( ! $#commands && ! st_other[state] )); then
    (( $#options )) && _describe -t options option options
    return
  fi
  local ret=1
  (( $#commands )) && _describe -t commands command commands && ret=0
  HELPERS_source $st_src[state] && ret=0
  return ret
}

# Sets $opt to the option named $1, matching long options by prefix when $2 is 1
HELPERS_find() {
  local i n first
  local -a matches
  for (( i=1; i<=$#opt_names; i++ )); do
    for n in ${=opt_names[i]}; do
      [[ $n = "$1" ]] && matches+=($i)
    done
  done
  if (( ! $#matches && $2 )); then
    for (( i=1; i<=$#opt_names; i++ )); do
      n=${${=opt_names[i]}[1]}
      if [[ $n = "$1"* ]]; then
        [[ -n $first && $first != "$n" ]] && return 1
        first=$n
        matches+=($i)
      fi
    done
  fi
  (( $#matches )) || return 1
  opt=$matches[1]
  for i in $matches; do
    if (( ${${=st_opts[state]}[(Ie)$i]} )); then
      opt=$i
      return 0
    fi
  done
  return 0
}

# Adds the candidates of source set $1
HELPERS_source() {
  local ret=1
  case $1 in
    "SOURCES"
  esac
  return ret
}

if [[ $zsh_eval_context[-1] = loadautofunc ]]; then
  FN "$@"
else
  compdef FN "PROG"
fi
